// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 sequenceNumber_,
        bytes32 batcherHash_,
        uint256 l1FeeOverhead_,
        uint256 l1FeeScalar_
    ) public {
        // The depositor account defaults to address(0); calling from it passes the
        // require in both versions, so the whole admissible domain is exercised.
        vm.prank(address(0));
        c.setL1BlockValues(
            number_,
            timestamp_,
            basefee_,
            hash_,
            sequenceNumber_,
            batcherHash_,
            l1FeeOverhead_,
            l1FeeScalar_
        );
        // Reference: no state variable is ever written by setL1BlockValues.
        assertTrue(c.sequenceNumber() == 0);
    }
}
